// pages/Profile.jsx

import React, { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../context/AuthContext';
import { fetchMyCoupons } from '../api/couponApi';
import { fetchReviews } from '../api/reviewApi';
import ReviewCard from '../components/ReviewCard';
import { useNavigate } from 'react-router-dom';

function Profile() {
  const { user } = useContext(AuthContext);
  const [myReviews, setMyReviews] = useState([]);
  const [coupons, setCoupons] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const load = async () => {
      try {
        if (!user) return;
        const res = await fetchReviews({ page: 1, limit: 20 });
        // 필터: 현재 유저의 리뷰만 (서버 필터가 있으면 사용 권장)
        setMyReviews(res.data.filter(r => r.author && String(r.author._id) === String(user.id)));

        const cRes = await fetchMyCoupons();
        setCoupons(cRes.data || []);
      } catch (err) {
        console.error(err);
      }
    };
    load();
  }, [user]);

  return (
    <div style={{ padding: 20 }}>
      <h1>👤 {user ? user.username : '프로필'}</h1>
      <div style={{ marginTop: 12 }}>
        <h3>내가 작성한 리뷰</h3>
        {myReviews.length === 0 ? (
          <p style={{ color: '#999' }}>아직 작성한 리뷰가 없습니다.</p>
        ) : (
          myReviews.map(r => <ReviewCard key={r._id} id={r._id} username={r.author?.username} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />)
        )}
      </div>

      <div style={{ marginTop: 20 }}>
        <h3>내 쿠폰</h3>
        {coupons.length === 0 ? (
          <p style={{ color: '#999' }}>쿠폰이 없습니다.</p>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 12 }}>
            {coupons.map(c => (
              <div key={c._id} style={{ padding: 12, borderRadius: 8, background: '#fff', boxShadow: '0 6px 16px rgba(0,0,0,0.04)' }}>
                <div style={{ fontSize: 14, fontWeight: 700 }}>{c.brand}</div>
                <div style={{ marginTop: 6 }}>코드: <strong>{c.code}</strong></div>
                <div style={{ marginTop: 6 }}>{c.discount}%</div>
                <button onClick={() => navigate('/coupons')} style={{ marginTop: 10, padding: '8px 10px', borderRadius: 8, background: '#0070f3', color: '#fff', border: 'none' }}>쿠폰센터로 이동</button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Profile;
